WITH payload AS (SELECT $archive_payload$[{"id":"ea51e365-2b8f-5c14-96e1-f7e3e27e1605","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حيازة مسكر -الدفع بصدور حكم سابق عليه باحلد -تداخل احلدود اذا كانت من جنس واحد -التعزير بالسجن .","document_number":"34349727","case_number":"32248103","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/04","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حيازة مسكر -الدفع بصدور حكم سابق عليه باحلد -تداخل احلدود اذا كانت من جنس واحد -التعزير بالسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34349727 :‬تاريخه ‪1434/11/04 :‬هـ‬\n                        ‫رقم الدعوى ‪32248103 :‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34391635:‬تاريخه‪1434/12/29:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬حيــازة‬\n      ‫مســكر ‪ -‬الدفــع بصــدور حكــم ســابق عليــه باحلــد ‪ -‬تداخــل احلــدود اذا‬\n                               ‫كانــت مــن جنــس واحــد ‪ -‬التعزيــر بالســجن ‪.‬‬\n\n\n\n\n      ‫‪ -1‬لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ( شــاربها‬\n      ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                                   ‫وأكل ثمنهــا ) ‪.‬‬\n      ‫‪ -2‬قــال ابــن قدامــة يف املغنــي ‪ ( 381/12‬وجملتــه أن مــا يوجــب احلــد‬\n      ‫مــن الزنــى والســرقة والقــذف وشــرب اخلمــر إذا تكــرر قبــل إقامــة احلــد‬\n                                          ‫أجــزأ حــد واحــد بغيــر خــاف علمنــاه ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n      ‫وقيادتــه الســيارة حتــت تأثيــره ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه بحــد املســكر وتعزيــره لقــاء احليــازة ‪ ،‬وإفهامــه أن عقوبتــه عائــدة‬\n      ‫للجهــة املختصــة لقــاء قيــادة الســيارة حتــت تأثيــر املســكر ‪،‬وحيــث‬\n      ‫قبــض علــى املدعــى عليــه مــن قبــل الدوريــات األمنيــة لالشــتباه بــه كونــه‬\n      ‫بحالــة غيــر طبيعيــة وبتفتيــش الســيارة عثــر بهــا علــى قارورتــن بهمــا‬\n\n‫‪55‬‬\n\f‫مســكر ‪،‬وباستشــمام املدعــى عليــه لوحــظ انبعــاث رائحــة املكســر‬\n‫مــن أنفاســه أثبــت التقريــر الكيميائــي إيجابيــة العينــة ملــادة الكحــول‬\n‫االيثيلــي ‪،‬وصــادق املدعــى عليــه علــى الدعــوى ‪،‬وأضــاف أنــه شــرب‬\n‫املســكر يف ‪ 1432/11/20‬ومت محاكمتــه قبــل يومــن مــن هــذه‬\n‫اجللســة وصــدر عليــه حكــم بحــد املســكر ‪،‬وجــرى االطــاع علــى‬\n‫صــك احلكــم الصــادر عليــه ‪،‬ومبــا أنــه صــدر حكــم علــى املدعــى‬\n‫عليــه بحــد املســكر فــا يحــد املدعــى عليــه لقــاء شــرب املســكر يف‬\n‫القضيــة املنظــورة ‪ ،‬ولالكتفــاء باحلكــم الســابق الصــادر عليــه املشــار‬\n‫إليــه ‪،‬ولثبــوت حيــازة املدعــى عليــه للمســكر بقصــد الشــرب ‪،‬فقــد‬\n‫حكمــت احملكمــة بتعزيــره لقــاء ذلــك بســجنه عشــرة أيــام ‪،‬وإفهامــه‬\n‫بــأن عقوبتــه لقيادتــه الســيارة حتــت تأثيــر املســكر عائــدة للجهــة‬\n‫املختصــة لقيادتــه للســيارة حتــت تأثيــر املســكر ‪،‬وقنــع املدعــى عليــه‬\n‫‪،‬وصــدق‬\n      ‫باحلكــم ‪،‬واعتــرض املدعــي العــام بــدون الئحــة اعتراضيــة ُ‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪.....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبناء على املعاملة احملالة لنا من‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪32248103‬‬\n‫وتاريــخ ‪ 1432/06/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32776394‬وتاريخ‬\n‫‪ 1432/06/26‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/11/04‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 08 : 00‬وفيها قدم املدعي العام ‪.....‬الئحة دعوى عامة‬\n‫ا فيهــا حيــث إنــه باالطــاع‬   ‫‪ .....‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬قائـ ً‬\n\n                                                                                        ‫‪56‬‬\n\f     ‫علــى محضــر الضبــط املعــد مــن قبــل دوريــات األمــن املتضمــن القبــض‬\n     ‫علــى املدعــى عليــه وبرفقتــه شــخص آخــر (أفــرج عنــه مــن قبــل جهــة‬\n     ‫الضبــط لعــدم صلتــه بالقضيــة) لالشــتباه بــه كونــه بحالــة غيــر طبيعيــة‬\n     ‫وبتفتيــش الســيارة عثــر بهــا علــى قارورتــن أثبــت التقريــر الكيمــاوي‬\n     ‫الشــرعي رقــم (‪ ).....‬يف تاريــخ ‪1432/5/5‬ه ـ ثبــت احتواء قارورتني على‬\n     ‫مــادة الكحــول االيثيلــي وبنســبة مســكرة وباستشــمام املدعــى عليــه‬\n     ‫لوحــظ انبعــاث رائحــة املســكر تفــوح مــن أنفاســه وباســتجواب املدعــى‬\n     ‫عليــه أقــر بتناولــه املســكر وحيازتــه لــه لقصــد الشــرب وأنكــر قيــادة‬\n     ‫الســيارة وهــو حتــت تأثيــر املســكر وبســؤاله عــن كيفيــة احلصــول علــى‬\n     ‫املســكر أفــاد بأنــه كان قــادم بهــا مــن ‪ .....‬وتناوله هنــاك ‪ .....‬وقد انتهى‬\n     ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بشــرب املســكر وقيــادة‬\n     ‫الســيارة حتــت تأثيــره وحيــازة قارورتــن مــن املســكر املصنــع محلي ـ ًا‬\n     ‫بقصــد الشــرب وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى‬\n     ‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل‬\n     ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات‬\n     ‫مــا أســند إليــه واحلكــم عليــه بحــد املســكر لقــاء شــربه لــه واحلكــم‬\n     ‫عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره لقــاء حيازتــه املســكر بقصــد‬\n     ‫الشــرب واثبــات قيادتــه للســيارة حتــت تأثيــر شــرب املســكر وفق ـ ًا‬\n     ‫للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه‬\n     ‫أن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة (‪ )68‬مــن نظــام املــرور‬\n     ‫تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم‬\n     ‫(‪ )315‬يف ‪1428/10/24‬ه ـ هــذه دعــواي وبســؤال املدعــى عليــه عــن‬\n     ‫الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى كلــه صحيــح ففــي تاريــخ‬\n\n\n‫‪57‬‬\n\f‫‪1432/4/24‬ه ـ اشــتريت مــن شــخص هنــدي اجلنســية يف حــي ‪.....‬باخلبــر‬\n‫قارورتــن مــاء صحــة صغيرتــي احلجــم مملوءتــن بالعــرق املســكر‬\n‫املصنــع محليـ ًا وشــربت مــن هــذا العــرق املســكر وقمــت بقيــادة الســيارة‬\n‫علي من قبل الدورية األمنية يف ســاعة‬      ‫حتت تأثير املســكر ومت القبض ّ‬\n‫متأخــرة مــن الليــل علــى طريــق الدمــام عندمــا كنــت أقــود ســيارتي نــوع‬\n‫‪....‬وأنــا بحالــة ســكر وقــد وجــدوا بحوزتــي القارورتــن اللتــن حتتويــان‬\n‫علــى العــرق املســكر املصنــع محلي ـ ًا وهمــا تعــودان لــي بقصــد الشــرب‬\n‫هــذا مــا حصــل وأنــا نــادم علــى فعلــي وتائــب إلــى اهلل تعالــى علمـ َا بأنــي‬\n‫شــربت املســكر يف تاريــخ ‪1432/11/20‬ه ـ ومت محاكمتــي يــوم األحد‬\n‫املاضــي لــدى القاضــي يف هــذه احملكمــة الشــيخ ‪.....‬وقــد حكم بجلدي‬\n‫احلــد ثمانــن جلــدة دفعــة واحــدة واكتســب احلكــم القطعيــة بقناعتــي‬\n‫وعــدم معارضــة املدعــي العــام هكــذا أجــاب بعــد ذلــك جــرى الرجــوع‬\n‫إلــى اللفــة رقــم (‪ )23‬وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو‬\n‫كمــا ذكــر املدعــي العــام يف دعــواه كمــا جــاء يف التقريــر الكيمــاوي‬\n‫أن القارورتــن صغيرتــي احلجــم ثــم جــرى االطــاع علــى صــورة القــرار‬\n‫الشــرعي رقــم ‪ 34347142‬يف ‪1434/11/2‬ه ـ الصــادر مــن فضيلــة‬\n‫القاضــي يف هــذه احملكمــة الشــيخ ‪.....‬وقــد جــاء يف دعــوى املدعــي العــام‬\n‫فيــه أنــه مت القبــض علــى املدعــى عليــه ‪.....‬يف تاريــخ ‪1432/11/20‬ه ـ‬\n‫واتضــح أنــه بحالــة ســكر وقــد حكــم فضيلــة القاضــي الشــيخ ‪.....‬‬\n‫بجلــد املدعــى عليــه مفلــح حــد املســكر ثمانــن جلــدة دفعــة واحــدة وقنــع‬\n‫املدعــى عليــه باحلكــم ولــم يعتــرض املدعــي العــام ويــوم نظــر الدعــوى‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬ ‫هــو األحــد ‪1434/11/2‬ه ـ فبنـ ً‬\n‫وحيــث أقــر املدعــى عليــه بشــرب املســكر يف تاريــخ ‪1432/4/25‬ه ـ‬\n\n\n                                                                                        ‫‪58‬‬\n\f     ‫وحيازتــه بقصــد الشــرب وقيــادة الســيارة حتــت تأثيــر املســكر وحيــث‬\n     ‫إن فعــل املدعــى عليــه مــن كبائــر الذنــوب فقــد لعــن رســول اهلل صلــى‬\n     ‫اهلل عليــه وســلم يف اخلمــر ثمانيــة (شــاربها وســاقيها وحاملهــا واحملمولــة‬\n     ‫إليــه وعاصرهــا ومعتصرهــا وبائعهــا واكل ثمنهــا) واللعــن ال يكــون إال‬\n     ‫علــى كبيــرة مــن كبائــر الذنــوب وحيــث إنــه قــد صــدر القرار الشــرعي‬\n     ‫رقــم ‪ 34347142‬يف ‪1434/11/2‬ه ـ بجلــد املدعــى عليــه حــد املســكر‬\n     ‫لقــاء شــربه للمســكر يف تاريــخ ‪1432/11/20‬ه ـ وعليــه فــا يحــد‬\n     ‫املدعــى عليــه لقــاء شــرب املســكر يف القضيــة املنظــورة قــال ابــن قدامــة‬\n     ‫رحمــه اهلل تعالــى يف املغنــى (‪« )381/12‬وجملتــه أن مــا يوجــب احلــد‬\n     ‫مــن الزنــى والســرقة والقــذف وشــرب اخلمــر إذا تكــرر قبــل إقامــة احلــد‬\n     ‫أجــزأ حــد واحــد بغيــر خــاف علمنــاه «وحيــث أبــدى املدعــى عليــه ندمــه‬\n     ‫وتوبتــه لــذا فقــد قــررت مــا يلــي ‪ :‬أو ًال ثبــت لــدي شــرب املدعــى عليــه‬\n     ‫للمســكر يف تاريــخ ‪1432/4/24‬ه ـ وقــررت االكتفــاء بجلــده احلــد‬\n     ‫احملكــوم بــه يف القــرار الشــرعي رقــم ‪ 34347142‬يف ‪1434/11/2‬ه ـ‬\n     ‫املشــار لــه ثاني ـاً‪ :‬ثبــت لــدي حيــازة املدعــى عليــه قارورتــن حتتويــان‬\n     ‫علــى العــرق املســكر املصنــع محليــا بقصــد الشــرب وقــررت تعزيــره‬\n     ‫لقــاء ذلــك بســجنه مــدة عشــرة أيــام اعتبــار ًا مــن تاريــخ إيقافــه ثالثـاً‪ :‬ثبــت‬\n     ‫لــدي قيــادة املدعــى عليــه للســيارة حتــت تأثيــر املســكر وأفهمتــه أن‬\n     ‫عقابــه علــى ذلــك عائــد للجهــة املختصــة ومبــا تقــدم حكمــت وبعــرض‬\n     ‫احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفي ـ ًا مبــا قــدم‬\n     ‫يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة التاســعة إال ثلــث وصلــى اهلل‬\n                                                                  ‫وســلم علــى نبينــا محمــد‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n‫‪59‬‬\n\f‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/2622301‬ج‪ 2‬وتاريــخ ‪1434/11/19‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 32/776394‬وتاريــخ ‪1434/11/12‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشيخ‪...../‬املســجل برقــم ‪34349727‬‬\n‫وتاريــخ ‪1434/11/4‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ...../‬يف‬\n‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                 ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/12/29‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪60‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":55,"source_page_end":60,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b1cc381cbfd2a90c69227c75070265620a24c239e15e173de53a5e3b644db81f","normalized_text_hash":"21dc77931e3669917667ce885e84345502034dc48810a2c959d6b050449d1e66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p55-34349727"},{"id":"dd50d5fa-7173-5c70-8475-882ee117bf32","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة املسكر -حد املسكر -التعزير بالسجن -عدم احلكم على املدعى عليه الثاني لعدم حضوره .","document_number":"3421215","case_number":"33225620","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/24","year":"1434","subject":"مسكر -شرب املسكر -حيازة املسكر -حد املسكر -التعزير بالسجن -عدم احلكم على املدعى عليه الثاني لعدم حضوره .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3421215 :‬تاريخه‪1434/1/24 :‬هـ‬\n                        ‫رقم الدعوى‪33225620:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34635253‬تاريخه‪1434/04/15:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيازة املســكر ‪ -‬حد املســكر ‪ -‬التعزير بالســجن‬\n                  ‫‪ -‬عــدم احلكــم علــى املدعــى عليــه الثانــي لعــدم حضوره ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــال تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n        ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n     ‫‪ -2‬مــا رواه ابــن عمــر رضــي اهلل عنــه أنــه صلــى اهلل عليــه وســلم قــال (‬\n                      ‫كل مســكر خمــر وكل خمــر حــرام ) أخرجــه مســلم ‪.‬‬\n     ‫‪ -3‬نقــل اإلجمــاع علــى حترميــه شــيخ اإلســام ابــن تيميــة كمــا يف‬\n     ‫الفتــاوى ‪ 218/34‬وقــال أيضــا( يجــب باتفــاق األئمــة أن يجلــد شــارب‬\n     ‫اخلمــر احلــد إذا ثبــت ذلــك عليــه وحــده ثمانــون جلــده باتفــاق األئمــة‬\n                                                                       ‫) ‪. 336/28‬‬\n                               ‫‪ -4‬املادة الثالثة من نظام االجراءات اجلزائية ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا حضــر األول منهمــا واآلخــر لــم‬\n     ‫يحضــر بحيــازة املســكر وشــربه ‪،‬طلــب إثبــات ما أســند إليهما واحلكم‬\n     ‫عليهمــا بحــد املســكر وتعزيرهمــا لقــاء احليــازة وتشــديد العقوبــة علــى‬\n     ‫األول لقــاء تعــدد الســوابق ‪ ،‬حيــث قبــض علــى املدعــى عليهمــا مــن قبــل‬\n\n‫‪61‬‬\n\f‫إحــدى فــرق دوريــات األمــن لشــربهما املســكر وباستشــمامها تبــن‬\n‫انبعــاث رائحــة املســكر منهمــا وأثبــت التقريــر الكيميائــي الشــرعي‬\n‫إيجابيــة العينــة ملــادة الكحــول صــادق املدعــى عليــه احلاضــر علــى دعــوى‬\n‫املدعــي العــام ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده ثمانــن‬\n‫جلــده حــد املســكر وتعزيــره بســجنه ثالثــة أشــهر لقــاء حيــازة املســكر‬\n‫وكثــرة ســوابقه وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n‫وصــدق‬\n     ‫الئحــة اعتراضيــة وتأجيــل احلكــم علــى الثانــي إلــى حضــوره ُ‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي املنــدوب باحملكمــة‬\n‫اجلزئيــة بالريــاض واملكلــف بعمــل املكتــب القضائــي رقــم (‪).....‬‬\n‫مبوجــب خطــاب التكليــف الصــادر مــن رئيــس احملكمــة اجلزائيــة‬\n‫بالريــاض املكلــف برقــم ‪ 331969270‬يف ‪1433/11/8‬ه ـ املبنــي علــى‬\n‫قــرار املجلــس األعلــى للقضــاء رقــم ‪ 3321434‬يف ‪1433/10/25‬ه ـ ويف‬\n‫يــوم الســبت ‪1434/1/24‬ه ـ ويف متــام الســاعة (‪ )01،00‬افتتحت اجللســة‬\n‫اخلاصــة بدعــوى املدعــي العــام ‪.....‬وفيهــا حضــر املدعــى عليــه ‪.....‬وادعــى‬\n‫املدعــي العــام قائــا بصف ــتي مدعيـ ـ ًا عامـ ـ ًا يف دائ ــرة االدع ــاء الع ــام‬\n                                        ‫مبدين ــة الري ــاض أدع ــي علــى كل مــن ‪/‬‬\n‫(‪ ..... )1‬البالــغ مــن العمــر‪ 40‬عام ـ ًا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬يقيــم يف مدينــة الريــاض ‪ -‬مفــرج عنــه بالكفالــة‬\n                                                                        ‫احلضوريــة ‪.‬‬\n‫(‪ ..... )2‬البالــغ مــن العمــر عام ـ ًا ؟ ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                        ‫‪62‬‬\n\f     ‫املدنــي رقــم (‪ ).....‬يقيــم يف مدينــة الريــاض ‪ -‬مفــرج عنــه بالكفالــة‬\n                                                                            ‫احلضوريــة ‪.‬‬\n     ‫بتاريــخ ‪1433/2/1‬ه ـ قبــض علــى املدعــى عليهمــا مــن قبــل إحــدى فــرق‬\n                                                ‫دوريــات األمــن لشــربهما املســكر ‪.‬‬\n     ‫وباستشــمامهما تبــن انبعــاث رائحــة كريهــة تشــبه املســكر مــن‬\n     ‫أفواههمــا وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).....‬‬\n     ‫لعام‪1432‬ه ـ احتــواء العينــة املرســلة للمــادة الكحــول باســتجوابهما‬\n     ‫اعترفــا بشــرب للمســكر وقــد أســفر التحقيــق عــن توجيــه االتهــام لهمــا‬\n                            ‫بشــرب املســكر وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافهمــا ًاملنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )13-11‬مــن‬\n                                              ‫ملــف التحقيــق املرفــق لفــة رقــم( ‪) 1‬‬\n                                             ‫‪ -2‬محضر القبض املرفق لفة رقم (‪)5‬‬\n                          ‫‪ -3‬التقرير الكيميائي الشرعي املرفق لفة رقم ( ‪)16‬‬\n     ‫وببحــث ســوابقهما أتضــح علــى األول وجــود ثــاث ســوابق حيــازة‬\n     ‫واســتعمال مخــدرات وســابقة واحــد ارتــكاب معاصــي وعــدم وجــود‬\n     ‫ســوابق مســجلة علــى الثانــي وحيــث إن مــا أقــدم عليــه املذكــوران فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا اســند إليهمــا واحلكــم‬\n     ‫عليهمــا بحــد املســكر لقــاء شــربهما لــه وبعقوبــة تعزيريــة لقــاء‬\n     ‫حيازتهمــا لــه وتشــديد العقوبــة بحــق األول لقــاء تعــدد ســوابقه التــي‬\n     ‫لــم تردعــه عقوباتهــا هكــذا ادعــى ‪ .‬وجــرى ســؤال املدعــى عليــه االول‬\n     ‫عــن مــا جــاء يف دعــوى املدعــي العــام فقــال مــا ذكــره املدعــي العــام‬\n     ‫يف دعــواه كلــه صحيــح جملــه وتفصيــا فقــد حــزت قــارورة صغيــره‬\n     ‫مــن املســكر وتعاطيتــه وقبــض علــي وأنــا بحالــة غيــر طبيعيــة هكــذا‬\n\n\n‫‪63‬‬\n\f‫أجــاب ومت تطبيــق املــادة ‪ 162‬مــن نظــام اإلجــراءات اجلزائيــة وحيــث‬\n‫أن اخلمــر محــرم بالكتــاب والســنه وإجمــاع العلمــاء قــال تعالــى ( إمنــا‬\n‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n‫لعلكــم تفلحــون ) وجــاء عنــه صلــى اهلل عليــه وســلم كمــا يف صحيــح‬\n‫مســلم مــن حديــث ابــن عمــر رضــي اهلل عنهمــا انــه صلــى اهلل عليــه‬\n‫وســلم قــال كل مســكر خمــر وكل خمــر حــرام ) ونقــل اإلجمــاع علــى‬\n‫حترميــه شــيخ اإلســام رحمــه اهلل كمــا يف الفتــاوي ج‪ 218/34‬وقــال‬\n‫أيضــا يجــب باتفــاق األئمــة أن يجلــد شــارب اخلمــر احلــد إذا ثبــت ذلــك‬\n‫عليــه وحــده ثمانــون جلــده باتفــاق األئمــة ج‪ 336/6/28‬وعليــه وبنــاء علــى‬\n‫املــادة رقــم (‪ )3‬مــن نظــام اإلجــراءات اجلزائيــة فقــد ثبــت لــدي حيــازة‬\n‫املدعــى عليــه األول لقــارورة مــن املســكر وتعاطيــه إيــاه وحكمــت عليه‬\n‫بجلــده ثمانــن جلــده حــد املســكر وســجنه ثالثــة اشــهر تعزيــرا لــه لقــاء‬\n‫احليــازة وكثــرة ســوابقه واجلــت احلكــم علــى املدعــى عليــه الثانــي حلــن‬\n‫إحضــاره وبعــرض احلكــم عليهمــا قــرر املدعــى عليــه القناعــة واملدعــي‬\n‫العــام عدمهــا وطلــب رفــع احلكــم إلــى محكمــة االســتئناف مكتفيــا‬\n‫بالئحــة الدعــوى هكــذا قــرر ومت قفــل اجللســة يف متام الســاعة (‪)01،30‬‬\n‫وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمد‬\n                             ‫والــه وصحبــه أجمعــن حــرر يف ‪1434/1/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض‬\n‫برقــم ‪ 34199788‬وتاريــخ ‪1434/3/8‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪...../‬املســجل برقــم ‪3421215‬‬\n‫وتاريــخ ‪ 1434/1/24‬ه ـ اخلــاص بدعــوى املدعــي العــام ضد‪...../‬ورفيقــه‬\n\n\n                                                                                      ‫‪64‬‬\n\f     ‫يف قضيــة شــرب مســكر علــى النحــو املوضــح بالقــرار وانتهــاء القضيــة‬\n     ‫بحكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة‬\n     ‫ضبطــه وأوراق املعاملــة لــم يظهــر موجــب للمالحظــة مــع تنبيــه فضيلتــه‬\n     ‫إلــى تدويــن اســم املدعــي العــام وفقــا للمــادة ‪ 156‬مــن نظــام اإلجــراءات‬\n                                                         ‫اجلزائيــة وبــاهلل التوفيــق ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":61,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fec2e39e14ff7b715ee4b5876e845415daa0057b2a461bbef74cc66e294a9073","normalized_text_hash":"fa8ea992bae36d3597e7e4cfb45ca057a74201ba9f7ca277583d3613f021a9c7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p61-3421215"},{"id":"84c19721-b4c5-5e88-80bc-9e035f11e448","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حضور حفل غنائي (شكشكة) -إنكار الدعوى -إقرار املدعى عليه حتقيق ا -احلدود تدرأ بالشبهات - تعزير بالسجن واجللد للشبهة -أخذ التعهد بعدم العودة ملثل ما","document_number":"348062","case_number":"33421240","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/11","year":"1434","subject":"مسكر -شرب املسكر -حضور حفل غنائي (شكشكة) -إنكار الدعوى -إقرار املدعى عليه حتقيق ا -احلدود تدرأ بالشبهات - تعزير بالسجن واجللد للشبهة -أخذ التعهد بعدم العودة ملثل ما","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 348062 :‬تاريخه‪1434/1/11:‬هـ‬\n                   ‫رقم الدعوى‪33421240:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 3428958:‬تاريخه‪1434/02/04:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حضــور حفــل غنائــي (شكشــكة) ‪ -‬إنــكار‬\n‫الدعــوى ‪ -‬إقــرار املدعــى عليــه حتقيق ـ ًا ‪ -‬احلــدود تــدرأ بالشــبهات ‪-‬‬\n‫تعزيــر بالســجن واجللــد للشــبهة ‪ -‬أخــذ التعهــد بعــدم العــودة ملثــل مــا‬\n                                                                    ‫يتهــم بــه ‪.‬‬\n\n\n\n\n              ‫‪ -1‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها ) ‪.‬‬\n                 ‫‪ -2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                         ‫ومالــه وعرضــه ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحضــور حفــل‬\n‫غنائي شكشكة واملشاركة فيه وطلب إثبات ما أسند إليه واحلكم‬\n‫عليــه بحــد املســكر وبعقوبــة تعزيريــة لقــاء حضــور احلفــل الغنائــي‬\n‫واملشــاركة فيــه ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل أعضــاء‬\n‫هيئــة األمــر باملعــروف والنهــي عــن املنكــر بداخــل اســتراحة وبرفقتــه‬\n‫مجموعــة أشــخاص بعــد ورود بــاغ مفــاده إقامــة حفــل غنائــي واالجتمــاع‬\n‫علــى شــرب املســكر وباستشــمام املدعــى عليــه اتضــح انبعــاث رائحــة‬\n                                                                                    ‫‪66‬‬\n\f     ‫املـ ـس ـك ــر مــن جوفه‪،‬أن ـك ـ ــر املدعــى عليــه دعــوى املدعــي العــام ‪،‬بينة‬\n     ‫املدعــي العــام اعتــراف املدعــى عليــه حتقيقـ ًا بشــرب املســكر وحضــور‬\n     ‫احلفــل الغنائــي ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره ألجــل‬\n     ‫التهمــة بســجنه أســبوعني وبجلــده ســبعني جلــدة علــى دفعتني متســاويتني‬\n     ‫وأخــذ التعهــد علــى املدعــى عليــه بعــدم العــودة ملثــل مــا يتهــم بــه وقنــع‬\n     ‫‪،‬وصــدق‬\n           ‫املدعــى عليــه باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                  ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫فلدي أنا‬\n           ‫َّ‬    ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n     ‫ـاء علــى املعاملــة الــواردة‬\n                                ‫‪.....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم‬\n     ‫ه ـ ف ‪ 6912/2/2‬وتاريخ‪1433/06/22‬ه ـ واملقيــدة بهــذه احملكمــة‬\n     ‫برقم‪331180937‬وتاريخ‪1433/06/23‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n     ‫الرئيــس برقم‪33421240‬وتاريخ‪1433/06/23‬ه ـ فتحت اجللســة األولى‬\n     ‫يوم السبت ‪1434/01/10‬هـ الساعة احلادية عشرة وفيها حضر املدعي‬\n     ‫العام‪.....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n     ‫رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء ذي الرقــم‬\n     ‫عامــا‬\n        ‫ا ‪ :‬فبصفتــي مدعيـ ًا ً‬      ‫‪.....‬والتاريــخ ‪1431/1/5‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n     ‫بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‪ 23 ،.....:‬عام ـاً‪،‬‬\n     ‫طالــب ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ،).....‬أوقــف‬\n     ‫بتاريــخ ‪1432 / 7 / 7‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ ‪1432/7/8‬ه ـ ‪،‬‬\n     ‫يقيــم يف األحســاء ‪ ......‬حيــث أنــه مت القبــض عليــه بتاريــخ ‪ 1432/7/7‬ه ـ‬\n\n‫‪67‬‬\n\f‫مــن قبــل رجــال هيئــة األمــر باملعــروف والنهــي عــن املنكــر مبركــز ‪.....‬‬\n‫بداخــل اســتراحة ‪.....‬بقريــة ‪.....‬وبرفقتــه مجموعــة أشــخاص (فــرزت لهــم‬\n‫أوراق مســتقلة وأحيلــت للجنــة العفــو) بعــد ورود بــاغ مفــاده إقامــة حفــل‬\n‫غنائــي (شكشــكة) واالجتمــاع علــى شــرب املســكر ‪ .‬وباستشــمام‬\n‫املدعــى عليــه اتضــح انبعــاث املسـ ــكر مــن جوفــه ‪ .‬وباســتجواب املدعــى‬\n‫عليــه أقــر بصحــة واقعــة القبــض عليــه ‪ ،‬وأنــه قــام بشــرب الكلونيــا‬\n‫بداخــل ســيارته وقــد حصــل عليهــا عــن طريــق الشــراء مــن شــخص ال‬\n‫يعرفــه مببلــغ قــدرة عشــرة ريــاالت ‪ ،‬ثــم قــام بالدخــول إلــى االســتراحة‬\n‫وحضــور احلفــل الغنائــي ‪.‬وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه‬\n‫بشــرب املســكر وحضــور حفــل غنائــي (شكشــكة) واملشــاركة فيــه‬\n                                                    ‫؛ وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                                            ‫‪ -1‬إقراره املدون على اللفة رقم ( ‪. ) 39‬‬\n                                  ‫‪ -2‬محضر القبض املرفق على اللفة رقم (‪. )6‬‬\n                        ‫‪ -3‬محضر االستشمام املنوه عنه املرفق لفة رقم (‪. )2‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ســابقة جتمـ ـهـ ــر‬\n‫وإزعـ ـ ــاج ‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ؛ أطلــب إثبــات مــا‬\n                                              ‫أســند إليــه ‪ ،‬واحلكــم عليــه باآلتــي ‪:‬‬\n                                                     ‫‪ -1‬بحد املسكر لقاء شربه له ‪.‬‬\n‫‪ -2‬بعقوبــة تعزيريــة ل ـ ــقاء حضــوره لل ـحـ ـف ـ ــل الغنائــي وامل ـ ـش ــارك ـ ـ ــة‬\n‫فيــه ‪ .‬عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى‬\n‫ا ‪ :‬مــا ذكــره املدعــي‬      ‫عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n‫العــام مــن اتهامــي بشــرب املســكر وحضــور حفـ ٍـل غنائــي واملشــاركة‬\n\n\n                                                                                               ‫‪68‬‬\n\f     ‫فيــه كل ذلــك غيــر صحيــح والصحيــح أننــي رأيـ ُـت زحمــة عنــد اســتراحة‬\n     ‫‪.....‬يف ‪.....‬فتوقفــت عندهــا ألرى مــاذا لديهــم وعنــد نزولــي مــن ســيارتي‬\n     ‫وقبــل دخــول االســتراحة قــام رجــال الهيئــة بضربــي والقبــض علـ َّـي‬\n     ‫وطلبــوا منــي اإلقــرار علــى هــذه الدعــوى ووعدونــي بإنهائهــا وإال فإنــه لــم‬\n     ‫أي خطــأ وصحيــح نســبة الســابقة لــي وهــي ســابقة جتمهــر‬                             ‫يصــدر منــي َّ‬\n     ‫وإزعــاج وقــد أخــذت محكوميتهــا هكــذا أجــاب ثــم جــرى ســؤال‬\n     ‫املدعــي العــام هــل لديــه بينــة علــى دعــواه فقــال ‪ :‬إننــي أكتفــي مبــا ورد‬\n     ‫يف أوراق املعاملــة هكــذا أجــاب عليــه فقــد جــرى االطــاع علــى جميــع‬\n     ‫أوراق املعاملــة ومنهــا ‪ :‬إقــرار املدعــى عليــه حتقيق ـ ًا املــدون علــى اللفــة‬\n     ‫(‪ )39‬املتضمــن مــا نصــه ‪ « :‬نعــم أقــر أنــا املواطــن ‪.....‬بأنــه وأثنــاء ســيري‬\n     ‫بالطريــق الزراعــي بقريــة ‪.....‬الحظــت وجــود حفــل غنائــي شــبابي بداخــل‬\n     ‫اســتراحة ‪.....‬فقمــت بعــد ذلــك بشــرب مــادة الكلونيــا القليــل منهــا مــن‬\n     ‫قــارورة كانــت معــي بالســيارة ومــن ثــم الدخــول إلــى االســتراحة حلضــور‬\n     ‫احلفــل الغنائــي وأمضيــت ربــع ســاعة وأنــا بداخــل االســتراحة ثــم قبــض‬\n     ‫علـ َّـي « ا‪.‬ه ـ ثــم جــرى االطــاع علــى كــرت ســوابق املدعى عليــه املتضمن‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬                ‫وجــود ســابقة جتمهــر وإزعــاج فبنـ ً‬\n     ‫وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وبعــد دراســة‬\n     ‫أن املدعــى عليــه أنكــر دعــوى املدعــي‬                            ‫أوراق املعاملــة وتأملهــا ومبــا َّ‬\n     ‫العــام باتهامــه بشــرب املســكر وحضــور حفـ ٍـل غنائــي واملشــاركة فيــه‬\n     ‫وال بينــة للمدعــي العــام علــى ذلــك ســوى إقــرار املدعــى عليــه حتقيق ـ ًا‬\n     ‫أن مــا‬   ‫وقــد رجــع عنــه ومبــا أ َّنــه يتهــم ألجــل ذلــك مبــا يتهــم بــه ومبــا َّ‬\n     ‫ض َب ْعـ َـد‬      ‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                  ‫ال ْر ِ‬                          ‫يتهــم بــه مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n                                                 ‫(وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n     ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن ) وقــال‬                           ‫ِإ ْص َلحِ َهــا ) وقــال تعالــى َ‬\n\n‫‪69‬‬\n\f‫دم ـ ُه وما ُل ـ ُه‬\n                 ‫ـرام ُ‬\n                    ‫صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n‫وعرضــه)) ممــا يســتوجب تعزيــر املدعــى عليــه ويتوجــه تخفيــف العقوبــة‬           ‫ُ‬\n‫عليــه لضعــف األدلــة عليــه لــذا كلــه وألجــل احلــق العــام حكمــت علــى‬\n‫ـدي إدانــة املدعــى عليــه بشــرب‬   ‫املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬لــم يثبــت لـ َّ‬\n‫املســكر وقــررت رد دعــوى املدعــي العــام بإثبــات ذلــك ‪ .‬ثاني ـ ًا ‪ /‬لــم‬\n‫ـدي إدانــة املدعــى عليــه حضــور حفـ ٍـل غنائــي واملشــاركة فيــه‬            ‫يثبــت لـ َّ‬\n‫وقــررت ر َّد دعــوى املدعــي العــام بإثبــات ذلــك ‪ .‬ويعــزر ألجــل التهمــة‬\n‫بســجنه ملــدة أســبوعني حتتســب منهــا املــدة التــي أوقــف فيهــا علــى ذمــة‬\n‫القضيــة وبجلــده ســبعون جلــدة علــى دفعتــن متســاويتني كل دفعــة‬\n‫خمســة وثالثــون دفعــة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة‬\n‫أيــام ‪ .‬ثالثـاً‪ /‬يؤخــذ عليــه التعهــد بعــدم العــودة ملثــل مــا يتهــم بــه ‪ .‬وبتــاوة‬\n‫احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر‬\n‫القناعــة بــه وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف دون الئحــة اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى‬\n‫وأقفلــت اجللســة الســاعة الثانيــة عشــرة وص َّلــى اهلل علــى نبينــا محمــد‬\n               ‫وعلــى آلــه وصحبــه وســلم أجمعــن ُحـ ِـر َر يف ‪1434/01/10‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/224020‬ج‪ 2‬وتاريــخ ‪1434/1/26‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫برقــم ‪ 331300381‬وتاريــخ ‪1434/1/24‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬املســجل برقــم ‪348062‬‬\n‫وتاريــخ ‪1434/1/11‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n\n\n                                                                                               ‫‪70‬‬\n\f     ‫قضيــة ســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/3‬ه ـ ‪.‬‬\n\n\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":66,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fc9b0c70d2e5e1b85f50a918b1805e5436a632dfb13ce1d2e541047c2531649e","normalized_text_hash":"68ab9ce62fcca88edc04d811ea44ea56efd46eb79e817d6682ef14cfc20d053e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p66-348062"},{"id":"79348195-309d-52e2-99d0-69392ddf818e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -تعاطي احلشيش املخدر -مقاومة رجال األمن -إقرار -إقامة حد املسكر -التعزير بالسجن واملنع من السفر .","document_number":"3432398","case_number":"33442420","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"مسكر -شرب املسكر -تعاطي احلشيش املخدر -مقاومة رجال األمن -إقرار -إقامة حد املسكر -التعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3432398:‬تاريخه ‪1434/2/9:‬هـ‬\n                  ‫رقم الدعوى ‪33442420:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 3457850‬تاريخه‪1434/03/08:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر‪ -‬تعاطي احلشــيش املخدر‪ -‬مقاومة رجال األمن‬\n      ‫‪ -‬إقرار‪ -‬إقامة حد املســكر‪ -‬التعزير بالســجن واملنع من الســفر ‪.‬‬\n\n\n\n\n‫‪ .1‬الفقــرة (‪ )2‬مــن املــادة ‪ 3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                 ‫العقليــة ‪.‬‬\n‫‪ .2‬الفقــرة (‪ )1‬مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                 ‫العقليــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وتعاطــي‬\n‫احلشــيش املخــدر وعــدم التجــاوب مــع رجــال األمــن ومقاومتهــم‬\n‫واالشــتباك معهــم ‪،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بحــد املســكر وبعقوبــة الســجن ومنعــه مــن الســفر وتعزيــره لقــاء‬\n‫عــدم جتاوبــه مــع رجــال األمــن واشــتباكه معهــم ‪،‬حيــث مت القبــض على‬\n‫املدعــى عليــه بعــد بــاغ مفــاده أن املدعــى عليــه بحالــة غيــر طبيعيــة يف‬\n‫منزلــه ومعــه آخريــن ‪،‬وإلقــرار املدعــى عليــه بشــرب املســكر وتعاطــى‬\n‫احلشــيش املخــدر مــع إنــكار عــدم التجــاوب مــع رجــال األمــن فقــد ثبــت‬\n‫إدانــة املدعــى عليــه بشــرب املســكر وتعاطــي احلشــيش املخــدر وعــدم‬\n\n                                                                                   ‫‪72‬‬\n\f     ‫التجــاوب مــع رجــال األمــن ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n     ‫بإقامــة حــد املســكر علــى املدعــى عليــه وتعزيــره بالســجن واملنــع مــن‬\n     ‫الســفر ‪،‬وبعــرض احلكــم علــى طــريف الدعــوى قنــع املدعــى عليــه وقــرر‬\n     ‫‪،‬وصــدق احلكــم مــن محكمــة‬     ‫املدعــي العــام االعتــراض بغيــر الئحــة ُ‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n     ‫اجلزائيــة‬\n        ‫ّ‬          ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n     ‫بالدمــام ويف يــوم األربعــاء املوافــق‪ .........‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n     ‫‪ 01 :‬وفيهــا قــدم املدعــي العــام ‪ ..........‬دعــواه ضــد املدعــى عليــه ‪........‬‬\n     ‫ا فيهــا ‪ :‬إنــه بتاريــخ ‪..........‬ه ـ ورد بــاغ إلى غرفة العمليات باجلهات‬    ‫قائـ ً‬\n     ‫األمنيــة عــن وجــود مبلــغ (ابــن املدعــى عليــه ) يدعــي علــى والــده بتواجده‬\n     ‫مــع شــخصني داخــل منزلهــم وهــم بحالــة غيــر طبيعيــة وبانتقــال الدوريــة‬\n     ‫األمنيــة إلــى املنــزل خــرج املدعــى عليــه واملتهمــن كل مــن ‪ ............‬و‬\n       ‫‪ ..........‬مت القبــض عليهــم وتســليمهم ملركــز الشــرطة مبحافظــة بقيــق‬\n     ‫«فــرزت أوراق مســتقلة للمتهمــن اآلخريــن وجــرى بعثهــا حملــل إقامتهمــا»‬\n     ‫وبضبــط أقــوال املبلــغ ابــن املدعــى عليــه األول (‪ )...‬البالــغ مــن العمــر(‪)..‬‬\n     ‫عامـ ًا أفــاد أنــه بعــد صــاة املغــرب مــن يــوم البــاغ ‪.......‬ه ـ حضــر والــده‬\n     ‫(‪ )...‬ومعــه شــخصان مــن أصدقائــه ودخلــوا إلــى مجلــس منزلهــم وقــام‬\n     ‫والــده بضربــه وذكــر املبلــغ أن املتهمــن املذكوريــن كانــوا جميع ـ ًا‬\n     ‫بحالــة غيــر طبيعيــة وأفــاد برغبتــه يف أخــذ التعهــد عليهــم بعــدم الدخــول‬\n     ‫للمنــزل وهــم يف حالــة ســكر فقــط وباستشــمام املدعــى عليــه واملتهمــن‬\n     ‫املرافقــن لــه املذكوريــن أعــا اتضــح انبعــاث رائحــة املســكر منهــم‬\n\n‫‪73‬‬\n\f‫جميعـ ًا وقــد أثبــت تقريــر الســموم الشــرعية رقــم(‪ 671‬م‪ .‬أ)وتاريــخ ‪.....‬هـ‬\n‫إيجابيــة عينــة التحليــل املأخــوذة مــن املدعــى عليــه ملركبــات احلشــيش‬\n‫املخــدر وقــد قــام رجــال األمــن بتدويــن محضــري إثبــات بعــدم جتــاوب‬\n‫املتهمــن املذكوريــن مــع رجــال األمــن أثنــاء طلــب حتليلهــم وقيــام‬\n‫املتهمــن باالشــتباك مــع رجــال األمــن أثنــاء إيداعهــم التوقيــف وقــد‬\n‫تعــذر ســماع أقوالهــم وقــت القبــض عليهــم كونهــم بحالــة غيــر طبيعيــة‬\n‫وبضبــط أقوالهــم مــن قبــل رجــال األمــن مبركــز الشــرطة تعــذر ذلــك‬\n‫ـداء كونهــم بحالــة ســكر ولعــدم إدراكهــم مــا يقولــون وبإعــادة‬         ‫ابتـ ً‬\n‫ضبــط أقوالهــم أفــاد أنــه مت القبــض عليهــم أثناء تواجــده مبنزله ويرافقه‬\n‫كل مــن ‪ ...‬و ‪ .....‬وأنكــر شــربهم املســكر وأقــر (‪ )..‬أنــه قــد ســبق لــه‬\n‫شــرب املســكر يف دولــة ‪ ......‬قبــل القبــض عليــه بأربعــة أيــام وأقــر أنــه‬\n‫رفــض االســتجابة لتحليلــه مــن قبــل رجــال األمــن وباســتجواب املدعــى‬\n‫عليــه ‪ :‬أقــر بواقعــة القبــض عليهــم أثنــاء تواجــده مبنزلــه بعــد أن تقــدم‬\n‫ابنــه بدعــوى عليهــم بســبب مشــاكل عائليــة بينــه وبــن أســرته كمــا‬\n‫أقــر بانــه يتعاطــى احلشــيش املخــدر وانتهــى التحقيــق التهامــه بشــرب‬\n‫املســكر وتعاطــي احلشــيش املخــدر وبعــدم التجــاوب مــع رجــال األمــن‬\n‫ومقاومتهــم واالشــتباك معهــم أثنــاء طلــب حتليلهــم وأثنــاء إيداعهــم دار‬\n‫التوقيــف وذلــك لألدلــة والقرائــن التاليــة ‪-1:‬إقــراره حتقيقـ ًا املنــوه عنــه‬\n‫واملرفــق صورتــه علــى اللفــات رقــم (‪ )11-9‬وعلــى اللفــة رقــم (‪-2 )15‬مــا‬\n‫جــاء يف محضــر القبــض املنــوه عنــه واملــدون علــى اللفــة رقــم(‪ -3 )3‬مــا‬\n‫جــاء يف تقاريــر الســموم الشــرعية املنــوه عنهــا واملرفقــة علــى اللفــات رقــم‬\n‫(‪ -4 )31-29‬مــا ورد مبحضــر تعــذر اســتجواب املدعــى عليــه املرفــق‬\n‫صورتــه باللفــة رقــم(‪ )7‬وبالبحــث عــن ســوابقه اتضــح أن لــه ســابقتي‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫مخــدرات وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــم بكامل أهليته‬\n     ‫ـب عليــه شــرع ًا أطلب مــا يلي ‪ :‬إثبات‬      ‫املعتبــرة شــرع ًا ‪ -‬فعــلٌ محــرم ومعاقـ ٌ‬\n     ‫إدانتــه مبــا ُأســند إيــه اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n     ‫رقــم(م‪ )39/‬وتاريخ‪1426/7/8‬ه ـ يف عقوباتــه األصليــة واحلكــم عليــه‬\n                                                                                          ‫باآلتــي‪:‬‬\n                                                          ‫‪ -1‬حد املسكر لقاء شربه له‬\n     ‫‪ -2‬بعقوبــة الســجن الــواردة يف الفقــرة األولــى من املــادة احلادية واألربعني‬\n     ‫مــن نظــام مكافحــة املخــدرات لقــاء تعاطيــه للحشــيش املخــدر وباملــادة‬\n                                        ‫الثالثــن مــن الالئحــة التنفيذيــة لــذات النظــام‬\n     ‫‪-3‬منعــه مــن الســفر بعــد تنفيــذ عقوبتــه وفقـ ًا ملــا تضمنتــه الفقــرة األولــى‬\n                            ‫مــن املــادة السادســة واخلمســن مــن النظــام املشــار إليــه‬\n     ‫‪ -4‬إثبــات إدانتــه لقــاء عــدم جتاوبــه لرجــال األمــن واالشــتباك معهــم‬\n                                 ‫واحلكــم عليــه بعقوبــة تعزيريــة وبــاهلل التوفيــق ‪.‬‬\n     ‫ويف هــذه اجللســة حضــر املدعــى عليــه ‪ ...........‬ســعودي اجلنســية مبوجــب‬\n     ‫بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ .........‬وبعــرض دعــوى املدعــي‬\n     ‫ا ‪ :‬صحيــح أننــي شــربت املســكر مــن نــوع ســنير‬             ‫العــام عليــه أجــاب قائـ ً‬\n     ‫وتعاطيــت احلشــيش املخــدر ولــم يصــدر علــي بعــد ذلــك حكـ ٌـم بحــد‬\n     ‫املســكر وبالفعــل ملــا طلــب منــي رجــال األمــن التحليــل رفضــت حتــى‬\n     ‫أتقابــل مــع املديــر ويف اليــوم الثانــي تقابلــت مــع املديــر ثــم ذهبــت للتحليــل‬\n     ‫وأمــا مــا ُذكــر مــن االشــتباك مــع رجــال األمــن فغيــر صحيــح حيــث أن‬\n     ‫أحــد رجــال األمــن قــام مبســك يــدي أثنــاء إدخالــي للتوقيــف فأنزلــت‬\n     ‫يــده عنــي هــذا مــا حصــل والســابقتني املذكورتــن يف الدعــوى تخصنــي‬\n\n\n‫‪75‬‬\n\f‫وبســؤال املدعــي العــام هــل لديــه بينــة علــى مــا مت إنــكاره مــن قبــل‬\n‫ا ‪ :‬ليــس لــدي ســوى مــا ورد يف الئحــة الدعــوى‬      ‫املدعــى عليــه أجــاب قائـ ً‬\n‫وأوراق املعاملــة ثــم جــرى االطــاع علــى صــورة مــن أقــوال املدعــى عليــه‬\n‫املرفقــة علــى اللفــات رقــم ( ‪ ) 9-11‬مــن طيــات املعاملــة وممــا تضمنتــه‬\n‫مــا نصــه ‪ ( :‬ملــاذا رفضــت الذهــاب إلــى املستشــفى لســحب العينــات ؟‬\n‫ج‪ -‬ألن طريقــة القبــض التــي متــت أمــام منزلــي هــي مــا دفعتنــي للرفــض )‬\n‫ا ‪ :‬نعم رفضت لهذا الســبب‬          ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫ولهــذا الســبب أيضــا طلبــت مقابلــة املديــر فنظــر ًا ملــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وحيــث أقــر املدعــى عليــه بشــرب املســكر وتعاطــي احلشــيش‬\n‫املخــدر ورفضــه لطلــب التحليــل ملــا طلــب منــه رجال األمن ذلــك وبرر هذا‬\n‫مبــا ذكــره أعــاه وأنكــر االشــتباك مــع رجــال األمــن وأقــر بإنــزال يــد‬\n‫أحــد رجــال األمــن حســب مــا ذكــر يف جوابــه أعــاه وبعــد االطــاع علــى‬\n‫طيــات املعاملــة ومــن ضمنهــا صــورة مــن محضــر عــدم جتــاوب بتاريــخ‬\n‫‪ ......‬ه ـ املرفــق علــى اللفــة رقــم ( ‪ ) 25‬مــن طيــات املعاملــة وممــا تضمنــه‬\n‫أن املدعــى عليــه ‪.......‬و‪ .....‬بعــد أن ُطلــب منهــم اإلحالــة للمستشــفى‬\n‫لســحب العينــات رفضــوا ذلــك وأبــدوا عــدم التجــاوب واالشــتباك مــع‬\n‫أفــراد الســرية أثنــاء إيداعهــم يف دار التوقيــف ويف صــورة هــذا احملضــر‬\n‫مــا يوجــه التهمــة يف حــق املدعــى عليــه باالشــتباك مــع رجــال األمــن وبعــد‬\n‫االطــاع علــى صــورة محضــر بتاريــخ ‪.......‬ه ـ املرفــق علــى اللفــة رقــم (‬\n‫‪ ) 24‬مــن طيــات املعاملــة وممــا تضمنــه أن كل مــن املدعــى عليــه ‪..........‬‬\n‫و ‪.......‬رافضــن الذهــاب للمستشــفى للتحليــل رفض ـ ًا تام ـ ًا ولــم ُيشــر يف‬\n‫هــذا احملضــر إلــى مــا ذكــره املدعــى عليــه مــن طلبــه للمديــر وحيــث‬\n‫ـاء علــى‬‫ـات لرجــال األمــن وبنـ ً‬ ‫أنــه لــم ُيشــر يف املعاملــة حلصــول أي إصابـ ٍ‬\n\n\n                                                                                         ‫‪76‬‬\n\f     ‫الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪56‬‬\n     ‫) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وحيــث أن معاقبــة‬\n     ‫املدعــى عليــه وفــق متقضــى الفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 41‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة إمنــا يكــون يف حالــة‬\n     ‫يوجــه ذلــك للمدعــى‬ ‫حيــازة شــي ٍء مــن املخــدرات بقصــد التعاطــي ولــم ّ‬\n     ‫عليــه يف هــذه الدعــوى لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوالً‪ -‬ثبــت‬\n     ‫لــدي إدانــة املدعــى عليــه بشــرب املســكر وقــررت جلــده حــد املســكر‬\n     ‫ثمانــن جلــدة دفع ـ ًة واحــده علن ـ ًا مبجمـ ٍـع مــن النــاس ‪ .‬ثاني ـاً‪ -‬ثبــت لــدي‬\n     ‫إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر واكتفيــت مبــا صــدر عليه‬\n     ‫مــن حــدٍ للمســكر املذكــور يف البنــد ( أو ًال ) ومنعــه مــن الســفر ملــدة‬\n     ‫ســنتني تبــدأ بعــد انتهــاء مــدة الســجن الصــادرة يف حقــه يف هــذا القــرار‬\n     ‫‪ .‬ثالث ـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه بعــدم التجــاوب مــع رجــال األمــن‬\n     ‫أثنــاء طلــب حتليلــه والتهمــة متوجهــة يف حقــه باالشــتباك معهــم ملــا ُذكــر‬\n     ‫مــن ضمــن احليثيــات أعــاه وقــررت تعزيــره لقــاء ذلــك كلــه بســجنه ملــدة‬\n     ‫ـداء مــن تاريــخ إيقافــه ‪ .‬رابعـاً‪ -‬عــدم اســتحقاق املدعــي‬ ‫خمســة أشــهر ابتـ ً‬\n     ‫العــام ملــا ُيطالــب مــن معاقبــة املدعــى عليــه وفــق مقتضــى الفقــرة ( ‪) 1‬‬\n     ‫مــن املــادة رقــم ( ‪ ) 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫ملــا ُذكــر مــن ضمــن احليثيــات أعــاه وبذلــك أجمــع حكمــت وبعــرض‬\n     ‫احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام‬\n     ‫االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف واكتفــى بالئحــة‬\n     ‫الدعــوى وأوراق املعاملــة عــن تقــدمي الئح ـ ٍة اعتراضيــة ف ُأجيــب لطلبــه‬\n                        ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافــق‪ ...../..0/28‬فتحــت‬\n\n\n‫‪77‬‬\n\f‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مبوجــب اخلطــاب رقــم ‪ ......‬يف ‪......‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة اجلزائيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية‬\n‫رقــم ‪ ......‬يف ‪......‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلاقــه‬\n                ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪78‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":72,"source_page_end":78,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f78dc11bda97898e5cb7117341a870cab105e41aba5598dd1730bc904b95e8e5","normalized_text_hash":"e13bb92d792fe8a061423659ae36071d3765f85893b2e2971c92ef56d809da5c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p72-3432398"},{"id":"668da353-12a0-520f-862d-ded0ca67dec5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -تعاطي املسكر -مدعى عليهما مفرج عنهما بكفالة -عدم حضورهما للمحكمة -عدم احلكم على الغائب .","document_number":"34254416","case_number":"33463588","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":"الدائرة اجلزائية السادسة مبحكمة الاستئناف مبكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/28","year":"1434","subject":"مسكر -تعاطي املسكر -مدعى عليهما مفرج عنهما بكفالة -عدم حضورهما للمحكمة -عدم احلكم على الغائب .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34254416 :‬تاريخه‪1434/6/28:‬هـ‬\n                        ‫رقم الدعوى‪33463588:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34317699‬تاريخه‪1434/09/13:‬هـ‬\n\n\n     ‫مســكر ‪ -‬تعاطــي املســكر ‪ -‬مدعــى عليهمــا مفــرج عنهمــا بكفالــة ‪ -‬عــدم‬\n                           ‫حضورهمــا للمحكمــة ‪ -‬عــدم احلكــم علــى الغائــب ‪.‬‬\n\n\n\n\n     ‫املــادة احلاديــة واألربعــن بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n     ‫ونصهــا (إذا لــم يحضــر املتهــم املكلــف باحلضــور حســب النظــام يف اليوم‬\n     ‫ا عنــه يف األحــوال‬ ‫املعــن يف ورقــة التكليــف باحلضــور ولــم يرســل وكيـ ً‬\n     ‫التــي يســوغ فيهــا التوكيــل فيســمع القاضــي دعــوى املدعــي وبيناتــه‬\n         ‫ويرصدهــا يف ضبــط القضيــة وال يحكــم إال بعــد حضــور املتهــم ) ‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا مفــرج عنهمــا بكفالــة‬\n     ‫حضوريــة بتعاطــي املســكر ‪،‬وطلــب إثبــات مــا أســند إليهمــا واحلكــم‬\n     ‫عليهمــا بحــد املســكر ‪ ،‬حيــث شــوهدت ســيارة مــن قبــل أعضــاء هيئــة‬\n     ‫األمــر باملعــروف والنهــي عــن املنكــر بداخلهــا املدعــى عليهمــا وهمــا‬\n     ‫بحالــة غيــر طبيعيــة وبعــد اســتيقافهما تبــن انبعــاث رائحــة املســكر‬\n     ‫منهمــا ‪،‬ولــم يحضــرا يف اجللســة احملــددة لنظرهــا وعليــه رفعــت اجللســة‬\n     ‫حلضورهمــا ‪،‬ويف اجللســة الثانيــة لــم يحضــرا لســماع إجابتهمــا ‪،‬ومبــا أنه‬\n\n‫‪79‬‬\n\f‫ال يحكــم علــى الغائــب يف القضايــا اجلنائيــة وفقــا للمــادة ‪ 141‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪،‬وبنــاء علــى مــا تقــدم قــرر القاضــي إعــادة املعاملــة‬\n‫ملصدرهــا وإفهــام املدعــي العــام بــأن لــه مواصلــة دعــواه متــى مــا أحضــر‬\n‫‪،‬وصــدق احلكــم‬  ‫املدعــى عليهمــا ‪،‬واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                    ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 33463588‬وتاريــخ ‪ 1433/07/14‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33174587‬وتاريــخ ‪ 1433/01/25‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق ‪ 1433/08/06‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 08‬وفيهــا حضــر املدعــي العــام ‪.....‬ســعودي اجلنســية بالســجل املدنــي‬\n‫رقــم (‪ ).....‬املفــوض لــه إقامــة الدعــوى بالتفويــض رقــم ‪.....‬وتاريــخ‬\n‫‪1427/11/14‬ه ـ ولــم يحضــر املدعــى عليهمــا ‪ .....‬و ‪.....‬وقــرر املدعــي‬\n‫العــام قائــا بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام مبحافظــة ينبــع‬\n‫ادعي على كال من ‪ 32..... -1/‬عاما ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ( ‪ ).....‬متــزوج موظــف قبــض عليــه بتاريــخ ‪1431/4/19‬ه ـ‬\n‫وأفــرج عنــه بالكفالــة احلضوريــة بتاريــخ ‪ 1431/4/22‬اســتنادا للمــادة‬\n‫‪ 120‬مــن نظــام اإلجــراءات اجلزائيــة يقيم مبحافظ ينبع ‪ 33..... -2-‬عاما‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ ).....‬متســبب أعــزب‬\n‫قبــض عليــه بتاريــخ ‪1431/4/19‬ه ـ وأفــرج عنــه بالكفالــة احلضوريــة‬\n‫بتاريــخ ‪1431/4/21‬ه ـ اســتنادا للمــادة ‪ 120‬مــن نظــام اإلجــراءات‬\n\n                                                                                      ‫‪80‬‬\n\f     ‫اجلزائيــة يقيــم مبحافظــة ينبــع حيــث انــه بتاريــخ ‪ 1433/4/19‬ه ـ وأثنــاء‬\n     ‫قيــام دوريــة هيئــة األمــر باملعــروف والنهــي عــن املنكــر مبحافظــة ينبــع‬\n     ‫بجولــة اعتياديــة شــوهدت ســيارة مــن نــوع التيمــا بداخلهــا املوضــح‬\n     ‫أســمائهما أعــاه بحالــة غيــر طبيعيــة وبعــد اســتيقافهما تبــن انبعــاث‬\n     ‫رائحــة الســكر مــن أفواههمــا وبســماع أقوالهمــا أقــرا بتعاطيهمــا مــادة‬\n     ‫املســكر وقــد انتهــى التحقيــق إلــى توجيــه االتهــام إليهمــا بتعاطــي مــادة‬\n     ‫املســكر وذلــك لألدلــة والقرائــن التاليــة ‪ -1-‬مــا جــاء يف أقوالهمــا‬\n     ‫املدونــة ص ( ‪ )4-1‬مــن دفتــر التحقيــق لفــة (‪ -2- )13‬مــا جــاء يف‬\n     ‫محضــر القبــض املرفــق لفــة (‪ )2‬وبالبحــث عــن ســوابقهما لــم تــرد حتــى‬\n     ‫تاريخــه وحيــث أن مــا أقــدم عليــه املذكــوران فعــل محــرم شــرعا أطلــب‬\n     ‫إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد املســكر لقــاء تعاطيهمــا‬\n     ‫لــه واهلل املوفــق انتهــى‪ .‬هــذا وألجــل حضــور املدعــى عليهمــا وعــرض مــا‬\n     ‫جــاء يف دعــوى املدعــي العــام عليهمــا وســماع مــا لديهمــا رفعــت اجللســة‬\n     ‫ـاء علــى تكليفنــا بالقيــام‬ ‫ويف يــوم الثالثــاء املوافق‪1434/06/27‬ه ـ وبنـ ً‬\n     ‫بأعمــال املكتــب القضائــي الســادس بخطــاب رئيــس احملكمــة العامــة‬\n     ‫املســاعد رقــم ‪/5‬أ تاريــخ ‪1434/04/27‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫العاشــرة والنصــف وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى‬\n     ‫عليهمــا ‪ .....‬و‪.....‬ونظــر ًا لعــدم حضــور املدعــى عليهمــا لســماع إجابتهمــا‬\n     ‫عــن دعــوى املدعــي العــام ومبــا أنــه ال يحكــم علــى الغائــب يف القضايــا‬\n     ‫اجلنائيــة إال بحضــوره وفقـ ًا للمــادة احلاديــة واألربعــن بعــد املائــة مــن نظــام‬\n     ‫اإلجــراءات اجلزائيــة ونصهــا ( إذا لــم يحضــر املتهــم املكلــف باحلضــور‬\n     ‫حســب النظــام يف اليــوم املعــن يف ورقــة التكليــف باحلضــور ولــم يرســل‬\n     ‫ا عنــه يف األحــوال التــي يســوغ فيهــا التوكيــل فيســمع القاضــي‬          ‫وكي ـ ً‬\n\n\n‫‪81‬‬\n\f‫دعــوى املدعــي وبيناتــه ويرصدهــا يف ضبــط القضيــة وال يحكــم إال‬\n‫بعــد حضــور املتهــم) أ‪ .‬ه ـ لــذا فقــد قــررت إعــادة املعاملــة ملصدرهــا‬\n‫وأفهمــت املدعــي العــام بــأن لــه مواصلــة دعــواه متــى مــا أحضــر املدعــى‬\n‫عليهمــا وبعــرض ذلــك علــى املدعــي العــام قــرر عــدم القناعــة وطلــب‬\n‫متييــزه والرفــع حملكمــة االســتئناف مكتفي ـ ًا بالئحــة الدعــوى العامــة‬\n‫فأجبتــه لطلبــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم حــرر يف ‪ 1434/06/27‬ه ـ‬\n‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد نحن قضاة‬\n‫الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة املكرمــة‬\n‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة بكتــاب‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم(‪)33174587‬‬\n‫وتاريــخ (‪1434/8/24‬هــ) املرفــق بهــا القــرار برقــم (‪)34254416‬‬\n‫وتاريــخ (‪1434/6/28‬هــ) الصــادر مــن فضيلــة الشــيخ‪..... /‬القاضــي‬\n‫باحملكمــة العامــة بينبــع‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪..... /‬‬\n‫ورفيقــه ســعوديي اجلنســية‪ ،‬املتهمــن يف شــرب املســكر احملكــوم فيــه‬\n‫مبــا دون باطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى‬\n‫اإلفهــام املذكــور‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                               ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪82‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":79,"source_page_end":82,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae77b0f433d26f33bdcb6f3f0a30cc1407fa7186f0cceb83d12479369b32b017","normalized_text_hash":"a2f207dc3ca56d03c999593caa30505efc13a94dac085d6708315dc8e5747194","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p79-34254416"},{"id":"749eb68b-a74e-5edd-977a-d74679179c9d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر وحيازته -حد املسكر علن ا -الهروب من رجال األمن -التعزير بالسجن واجللد -نظر المحكمة يف وقائع غير مدعى بها -إقامة حد املسكر بالرائحة مع قرينة أخرى -تعهد .","document_number":"33471037","case_number":"33489427","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"مسكر -شرب املسكر وحيازته -حد املسكر علن ا -الهروب من رجال األمن -التعزير بالسجن واجللد -نظر المحكمة يف وقائع غير مدعى بها -إقامة حد املسكر بالرائحة مع قرينة أخرى -تعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33471037‬تاريخه‪1433/11/30:‬هـ‬\n                       ‫رقم الدعوى‪33489427:‬‬\n                 ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 3427122:‬تاريخه‪1434/02/02:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب املســكر وحيازتــه ‪ -‬حــد املســكر علنـ ًا ‪ -‬الهــروب مــن رجــال‬\n     ‫األمــن ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬نظــر احملكمــة يف وقائــع غيــر‬\n     ‫مدعــى بهــا ‪ -‬إقامــة حــد املســكر بالرائحــة مــع قرينــة أخــرى ‪ -‬تعهــد ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قولــه تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n         ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n     ‫‪ -2‬مــا أخرجــه أبــو داود عــن ابــن عمــر رضــي اهلل عنهمــا أنــه صلــى‬\n     ‫اهلل عليــه وســلم قــال ( لعــن اهلل اخلمــر وشــاربها وبائعهــا ومبتاعهــا‬\n                      ‫وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة إليــه ) ‪.‬‬\n     ‫‪ -3‬قــرار هيئــة كبــار العلمــاء ‪ 53‬يف ‪1397/4/4‬ه مــن أن حــد املســكر‬\n     ‫يثبــت بوجــود رائحــة اخلمــر مــع وجــود قرينــة أخــرى يقتنــع بهــا‬\n     ‫القاضــي ومــن أن عقوبــة شــارب اخلمــر احلــد ال التعزيــر وأن مقــداره‬\n                                 ‫ثمانــون جلــده يتــم تنفيــذه جملــة واحــدة ‪.‬‬\n                            ‫‪ -4‬املادة السادسة من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي املســكر وحيازتــه‬\n     ‫وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر وعقوبــة‬\n     ‫تعزيريــة لقــاء حيــازة املســكر ‪ ،‬حيــث مت مشــاهدة ســيارة يف مــكان‬\n‫‪83‬‬\n\f‫مظلــم بــن أشــجار مــن قبــل الدوريــات األمنيــة ‪،‬وبالتوجــه إليهــا وعنــد‬\n‫مشــاهدة املدعــى عليــه للدوريــة الذ بالفــرار بســرعة جنونيــة واســتمرت‬\n‫الفرقــة مبتابعتــه حتــى مت اســتيقافه واتضــح بــأن رائحــة تشــبه رائحــة‬\n‫املســكر تنبعــث منــه كمــا عثــر علــى قــارورة بهــا مــادة ســائلة يشــتبه أن‬\n‫تكــون مــادة مســكرة ‪،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املضبوطــة ملــادة املســكر ‪ ،‬وأنكــر املدعــى عليــه الدعــوى ‪،‬‬\n‫وحضــر أفــراد الفرقــة القابضــة وشــهدا علــى مــا قــرره املدعــي العــام‬\n‫يف دعــواه وأنــه جــرى استشــمام املدعــى عليــه واتضــح انبعــاث رائحــة‬\n‫املســكر مــن فمــه وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة علنـ ًا يف مــكان عــام حــد املســكر وتعزيــره‬\n‫بالســجن مــدة شــهرين وجلــده خمســن جلــدة علن ـ ًا دفعــة واحــدة لقــاء‬\n‫حيازتــه للمســكر والهــروب مــن رجــال األمــن وأخــذ التعهــد عليــه بعــدم‬\n‫العــودة ملثــل مــا بــدر منــه ‪،‬واعتــرض املدعــى عليــه بالئحــة ولــم يعتــرض‬\n             ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬        ‫املدعــي العــام ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 33489427‬وتاريــخ ‪ 1433/07/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331411213‬وتاريــخ ‪ 1433/07/27‬ه ـ ففــي يــوم‬\n‫األحد املوافق ‪ 1433/08/18‬هـ افتتحت اجللسة الساعة ‪ 08 : 30‬بشأن‬\n‫دعــوى املدعــي العام‪.....‬واملكلــف مبهمة اإلشــراف على مكتب االدعاء‬\n‫العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس فــرع هيئــة التحقيــق‬\n\n                                                                                    ‫‪84‬‬\n\f     ‫واالدعــاء العــام مبنطقــة جنــران رقــم ‪.....‬وتاريــخ ‪1430/12/29‬ه ـ ضــد‬\n     ‫ا يف دعــواه‬   ‫‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.....‬قائ ـ ً‬\n     ‫عليه إنه ورد يف محضر دوريات مكافحة املخدرات رقم ‪1235/6/15‬‬\n     ‫وتاريــخ ‪1433/5/12‬ه ـ املتضمــن أنــه أثنــاء قيــام الدوريــة بعملهــا املعتــاد‬\n     ‫بالقــرب مــن كبــري ‪ .....‬حيــث مت مشــاهدة ســيارة يف مــكان مظلــم‬\n     ‫بــن أشــجار يف الــوادي حيــث مت االشــتباه فيهــا وبالتوجــه إليهــا وعنــد‬\n     ‫مشــاهدته للدوريــة الذ بالفــرار علــى طريــق احلضــن بســرعة جنونيــة ومت‬\n     ‫متابعتــه مــن قبــل الفرقــة حملاولــة اســتيقافه إال أنــه اســتمر بالهــروب ومت‬\n     ‫إطــاق طلقتــن بالهــواء إال أنــه لــم يتوقــف واســتمرت الفرقــة يف متابعتــه‬\n     ‫حتــى مت التضييــق عليــه ومت اســتيقافه وعنــد طلــب إثباتــه اتضــح أنــه‬\n     ‫املدعــى عليــه ‪ .‬وبتفتيشــه شــخصيا لــم يعثــر على أي شــيء مــن املمنوعات‬\n     ‫واتضــح أنــه تنبعــث منــه رائحــه يشــتبه أن تكــون رائحــة مســكر كمــا‬\n     ‫عثــر علــى قــارورة مــاء صحــة صغيــرة ســعة ‪600‬مــل بهــا النصــف مــن‬\n     ‫مــادة ســائلة يشــتبه أن تكــون مــادة املســكر ( عــرق ) كمــا عثــر علــى‬\n     ‫يف درج الســيارة علــى مبلــغ مالــي وقــدره تســعة وثمانــون ألــف وثالثمائــة‬\n     ‫ريــال وبســؤاله عــن ذلــك املبلــغ أفــاد بأنــه ليــس عائــد لــه وأنــه وضعــه لديه‬\n     ‫أمانــة شــخص يدعــى ‪..... /‬حتــى زواجــه وجــرى مســح موقــع هروبــه لــم‬\n     ‫يعثــر علــى أي شــيء مــن املمنوعــات كمــا جــرى االطــاع علــى محضــر‬\n     ‫االستشــمام املــؤرخ يف‪1433/5/12‬ه ـ املعــد مــن قبــل كل عضــو هيئــة‬\n     ‫األمــر باملعــروف والنهــي عــن املنكــر ورقيــب الفرقــة القابضــة املتضمــن‬\n     ‫أنــه باستشــمام املدعــى عليــه اتضــح انبعــاث رائحــة كريهــة تشــبه رائحــة‬\n     ‫املســكر تنبعــث مــن فمــه وباســتجواب املدعــى عليــه أقــر بحيازتــه ملــادة‬\n     ‫العــرق املســكر لغــرض اســتخدامها حيــث قــام بشــرائها مــن أحــد‬\n\n\n‫‪85‬‬\n\f‫العمالــة والوافــدة وأنــه قبــض عليــه مــن قبــل أفــراد مكافحــة املخــدرات‬\n‫وأن ســبب تواجــد يف املــكان املظلــم يف الــوادي شــرب املســكر وقــد‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بتعاطــي مــادة العــرق‬\n                      ‫املســكر وحيازتهــا وذلــك لألدلــة والقرائــن التاليــة‪0‬‬\n‫‪ :1‬مــا جــاء يف محضــر القبــض املعــد مــن قبــل دورية مكافحــة املخدرات‬\n                                                                       ‫لفــه رقــم (‪. )5‬‬\n‫‪ :2‬مــا جــاء يف محضــر االستشــمام واملــدون علــى ص رقــم (‪ )3‬مــن ملــف‬\n                                                 ‫التحقيــق املرفــق لفــه رقــم ( ‪.) 1‬‬\n‫‪ :3‬مــا جــاء يف التقريــر الفنــي وإيجابيــة العينــة املرســلة للفحــص علــى لفــة‬\n                                                                            ‫رقم (‪)46‬‬\n‫وبالبحــث عــن ســوابق للمدعــى عليــه لــم يعثــر لــه علــى ســوابق حتــى‬\n                                                                            ‫تاريخــه‪0‬‬\n‫وتأسيس ـ ًا علــى مــا ســبق وألن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n‫ا محرمـ ًا معاقبـ ًا عليــه شــرع ًا لــذا أطلــب‬\n                                                ‫أهليتــه املعتبــرة شــرع ًا يعــد فعـ ً‬\n                       ‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‬\n                                                                    ‫‪ :1‬حد املسكر‬\n‫‪ :2‬عقوبــة تعزيريــة لقــاء حيازتــه ملــادة العــرق املســكرة هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام‬\n‫مــن قيامــي بشــرب مــادة العــرق املســكر وحيازتهــا غيــر صحيــح جملــة‬\n‫ا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي العــام هــل لديــك‬        ‫وتفصيـ ً‬\n‫بينــة علــى مــا أنكــره املدعــى عليــه فقــال نعــم يوجــد لــدي بينــة وأطلــب‬\n‫إمهالــي إلحضارهــا يف اجللســة القادمــة فأجبتــه لطلبــه وقــررت رفــع‬\n‫اجللســة إلــى يــوم الســبت املوافــق ‪1433/9/2‬ه ـ الســاعة الواحــدة وبــاهلل‬\n\n\n                                                                                           ‫‪86‬‬\n\f     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫‪ .‬حــرر يف ‪ 1433/08/18‬ه ـ الســاعة ‪ 09:00‬احلمــد هلل وحــده وبعــد‬\n     ‫ففــي يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 12:00‬وفيهــا حضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه‬\n     ‫ال مــن‪..... -1 :‬‬‫التــي اســتعد بإحضارهــا يف اجللســة الســابقة أحضــر ك ً‬\n     ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .....‬و‪.......... -2‬ســعودي‬\n     ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .....‬وبســؤال الشــاهد األول عــن‬\n     ‫مــا لديــه مــن شــهادة قــال ( أشــهد بــاهلل بأنــي شــاهدت ســيارة يف مــكان‬\n     ‫مظلــم بــن أشــجار يف الــوادي وبعــد االشــتباه بهــا توجهــت إليهــا بصحبــة‬\n     ‫أفــراد الفرقــة وعنــد مشــاهدة قائــد الســيارة للدوريــة الذ بالفــرار علــى‬\n     ‫طريــق ‪ .....‬بســرعة جنونيــة ومتــت متابعتــه مــن قبــل الفرقــة حملاولــة‬\n     ‫اســتيقافه إال أنــه اســتمر بالهــروب ومت إطــاق طلقتــن بالهــواء إال أنــه‬\n     ‫لــم يتوقــف واســتمرت الفرقــة يف متابعتــه حتــى مت التضييــق عليــه ومت‬\n     ‫إســتيقافه وعنــد طلــب إثباتــه اتضــح أنــه املدعــى عليــه و بعــد تفتيشــه‬\n     ‫شــخصيا لــم يعثــر معــه علــى أي شــيء مــن املمنوعــات وبعــد تفتيــش‬\n     ‫ســيارته عثــرت بداخلهــا علــى قــارورة مــاء صحــة صغيــرة ســعة ‪600‬مــل‬\n     ‫بهــا النصــف مــن مــادة العــرق املســكر ثــم قمــت باستشــمام املدعــى عليه‬\n     ‫وقــد كانــت تنبعــث مــن فمــه رائحــة العــرق املســكر هــذا مــا لــدي وبــه‬\n     ‫أشــهد ) وبســؤال الشــاهد الثانــي عــن مــا لديــه مــن شــهادة قــال ( أشــهد‬\n     ‫بــاهلل بأنــي شــاهدت ســيارة يف مــكان مظلــم بــن أشــجار يف الــوادي‬\n     ‫وبعــد االشــتباه بهــا توجهــت إليهــا بصحبــة أفــراد الفرقــة وعنــد مشــاهدة‬\n     ‫قائــد الســيارة للدوريــة الذ بالفــرار علــى طريــق ‪.....‬بســرعة جنونيــة ومتــت‬\n     ‫متابعتــه مــن قبــل الفرقــة حملاولــة اســتيقافه إال أنــه اســتمر بالهــروب‬\n\n\n‫‪87‬‬\n\f‫ومت إطــاق طلقتــن بالهــواء إال أنــه لــم يتوقــف واســتمرت الفرقــة يف‬\n‫متابعتــه حتــى مت التضييــق عليــه ومت اســتيقافه وعنــد طلــب إثباتــه اتضــح‬\n‫أنــه املدعــى عليــه و بعــد تفتيشــه شــخصيا لــم يعثــر معــه علــى أي شــيء‬\n‫مــن املمنوعــات وبعــد تفتيــش ســيارته عثــرت بداخلهــا علــى قــارورة مــاء‬\n‫صحــة صغيــرة ســعة ‪600‬مــل بهــا النصــف مــن مــادة العــرق املســكر ثــم‬\n‫قمــت باستشــمام املدعــى عليــه وقــد كانــت تنبعــث مــن فمــه رائحــة‬\n‫العــرق املســكر وقــد ســألته عــن ســبب قيامــه بالهــروب فأجابنــي بأنــه‬\n‫كان يقــوم بشــرب العــرق املســكر هــذا مــا لــدي وبــه أشــهد ) وبعــرض‬\n‫مــا ذكــره الشــاهدان علــى املدعــى عليــه قــال مــا ذكــره الشــاهدان يف‬\n‫ا هكــذا أجــاب ثــم جــرى تعديــل‬     ‫شــهادتهما غيــر صحيــح جملــة وتفصيـ ً‬\n                                                 ‫الشــاهدين مــن قبــل كل مــن‪:‬‬\n                                                              ‫‪ ..... -1‬و ‪.......... -2‬‬\n‫وقــاال نشــهد بــأن الشــاهدين عــدالن ثقتــان مرضيــا الشــهادة هكــذا‬\n‫شــهدا وللتأمــل ودراســة القضيــة رفعــت اجللســة إلــى يــوم الســبت املوافــق‬\n‫‪1433/11/27‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/24‬ه ـ‬\n                                                                    ‫الســاعة ‪12:30‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1433/11/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09:00‬وفيهــا حضــر املدعــى عليــه وجــرى منــي‬\n‫ســؤال املدعــي العــام هــل لديــك زيــادة بينــة فقــال ليــس لــدي زيــادة بينــة‬\n‫ســوى مــا جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق واالطالع‬\n‫علــى تقريــر إدارة األدلــة اجلنائيــة رقــم ‪/.....‬ســموم ومخــدرات ‪1433 /‬ه ـ‬\n‫املرفــق علــى لفــة رقــم (‪ )46‬وعلــى أقــوال املدعــى عليــه حتقيق ـ ًا املدونــة‬\n\n\n                                                                                         ‫‪88‬‬\n\f     ‫علــى ص ‪ 13-11‬مــن امللــف املرفــق علــى لفــة رقــم (‪ )1‬فبنــاء علــى مــا‬\n     ‫ســبق مــن الدعــوى واإلجابــة و ملــا كان مــن املقــرر نظام ـ ًا جــواز نظــر‬\n     ‫احملكمــة يف وقائــع غيــر مدعــى بهــا مــن املدعــي العــام ممــا ال يحتــاج‬\n     ‫إلــى حتقيــق مبوجــب املــادة السادســة مــن نظــام اإلجــراءات اجلزائيــة‬\n     ‫وحيــث إن الشــاهدين اللذيــن أحضرهمــا املدعــي العــام قــد شــهدا علــى‬\n     ‫أن املدعــى عليــه كان يقــف بســيارته يف مــكان مظلــم بــن أشــجار‬\n     ‫الــوادي و أنــه عنــد مشــاهدته للدوريــة الرســمية قــام بالهــرب بســرعة‬\n     ‫جنونيــة و أنــه لــم يتوقــف رغــم إطــاق طلقتــن ناريتــن بالهــواء و أنهمــا‬\n     ‫عثــرا بداخــل ســيارته علــى قــارورة مــاء صغيــرة ســعتها ‪ 600‬مــل يحتــوي‬\n     ‫نصفهــا علــى مــادة العــرق املســكرة وبنــاء علــى مــا جــاء يف تقريــر إدارة‬\n     ‫األدلــة اجلنائيــة رقــم ‪/.....‬ســموم ومخــدرات ‪1433 /‬ه ـ املتضمــن إيجابيــة‬\n     ‫العينــة املضبوطــة ملــادة املســكر وحيــث إن الشــاهدين قــد شــهدا علــى‬\n     ‫أن رائحــة العــرق املســكر كانــت تنبعــث مــن فــم املدعــى عليــه ومبــا أن‬\n                                        ‫هــذه الشــهادة قــد قويــت بالقرائــن اآلتيــة‪:‬‬\n     ‫‪ -1‬وجــود املدعــى عليــه يف مــكان مظلــم بــن أشــجار الــوادي وقيامــه‬\n                    ‫بالهــرب بســرعة جنونيــة عنــد مشــاهدته للدوريــة الرســمية‬\n     ‫‪ -2‬ثبــوت حيــازة املدعــى لقــارورة مــاء صغيــرة ســعتها ‪ 600‬مــل يحتــوي‬\n                                               ‫نصفهــا علــى مــادة العــرق املســكرة‬\n              ‫‪ -3‬إقرار املدعى عليه حتقيق ًا بحيازته العرق املسكر وتعاطيه‬\n     ‫‪ -4‬إقــرار املدعــى عليــه أمــام الشــاهد الثانــي بــأن ســبب قيامــه بالهــروب‬\n     ‫مــن رجــال األمــن هــو شــربه للعــرق املســكر التعاطــي و ملــا كان شــرب‬\n     ‫العــرق املســكر وحيازتــه أمــر ًا محرم ـ ًا يف الشــريعة اإلســامية بدليــل‬\n     ‫قولــه تعالــى‪ « :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n\n\n‫‪89‬‬\n\f          ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون»‬\n‫( املائــدة ‪ ) 90 :‬و مــا أخرجــه أبــو داود عــن ابــن عمــر رضــي اهلل عنهمــا‬\n‫أنــه قــال ‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم ‪ « :‬لعــن اهلل اخلمــر‬\n‫وشــاربها وســاقيها وبائعهــا و مبتاعهــا وعاصرهــا ومعتصرهــا وحاملهــا‬\n‫واحملمولــة إليــه « ( كتــاب األشــربة ‪ ،‬البــاب ‪ :‬العنــب يعصــر للخمــر‬\n‫‪ ،‬احلديــث رقــم ‪ )3189‬واســتناد ًا علــى مــا تضمنــه قــرار هيئــة كبــار‬\n‫العلمــاء رقــم ‪ 53‬وتاريــخ ‪1397/4/4‬ه ـ مــن أن ‪1397‬ه ـ مــن أن حــد‬\n‫املســكر يثبــت بوجــود رائحــة اخلمــر مــع وجــود قرينــة أخــرى يقتنــع بهــا‬\n‫القاضــي ومــن أن عقوبــة شــارب اخلمــر احلــد ال التعزيــر وأن مقــدراه‬\n‫ثمانــون جلــدة يتــم تنفيــذه جملــة واحــدة ‪ ،‬ونظــر ًا إلــى أنــه ال يوجــد لــدى‬\n‫املدعــى عليــه ســوابق جنائيــة ولقلــة الكميــة املضبوطــة معــه وتأسيسـ ًا‬\n‫علــى جميــع مــا تقــدم فقــد قــررت مــا يأتــي أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى‬\n‫عليــه بقيامــه بشــرب مــادة العــرق املســكرة وحيازتهــا بقصــد التعاطــي‬\n‫وهروبــه مــن رجــال األمــن ثاني ـ ًا ‪ :‬معاقبتــه بحــد املســكر وذلــك بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة علن ـ ًا يف مــكان عــام ثالث ـ ًا ‪ :‬تعزيــره وذلــك‬\n‫بســجنه ملــدة شــهرين تبــدأ اعتبــار ًا مــن تاريــخ إدخالــه الســجن وجلــده‬\n‫خمســن جلــدة علنـ ًا دفعــة واحــدة لقــاء حيازتــه العــرق املســكر بقصــد‬\n‫التعاطــي والهــروب مــن رجــال األمــن رابع ـ ًا ‪ :‬يؤخــذ التعهــد الشــديد‬\n‫علــى املدعــى عليــه بعــدم العــودة ملثــل مــا بــدر منــه هــذا مــا ظهــر لــي وبــه‬\n‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه لــم يقنــع بــه وطلــب رفــع‬\n‫احلكــم حملكمــة االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم نســخة‬\n‫احلكــم بعــد عشــرة أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن يومــا‬\n‫مــن التاريــخ احملــدد ال ســتالم نســخة احلكــم كمــا قــرر املدعــي العــام‬\n\n\n                                                                                            ‫‪90‬‬\n\f     ‫عــدم االعتــراض وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/29‬ه ـ الســاعة ‪09:30‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم‬\n     ‫‪ 331521548‬وتاريــخ ‪1434/1/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 33471037‬وتاريــخ‬\n     ‫‪1433/11/30‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪..... /‬يف قضيــة‬\n     ‫( ســكر ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n     ‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‬\n                         ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪91‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":83,"source_page_end":91,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7b53f5454a75d3d391499693370e7401af456da59357cd56396b28d3d31babd7","normalized_text_hash":"e8f58cc7af89be41228a514741d04e3f14d3d8ec337db29399447f9ac32438eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p83-33471037"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

